  "established": [
    {
      "text": "来访者是母亲的主要照顾者，持续承担陪伴复诊、分药、居家防摔改造等具体任务。",
      "evidence_ids": [
        "P02-S01-U01",
        "P02-S01-U07",
        "P02-S01-U13",
        "P02-S03-U01",
        "P02-S03-U05"
      ]
    },
    {
      "text": "来访者在照顾中反复体验到内疚与需要个人空间/喘息的冲突，并用‘没良心’、‘找借口’等自我责备压制自己的需要。",
      "evidence_ids": [
        "P02-S01-U03",
        "P02-S01-U05",
        "P02-S01-U09",
        "P02-S01-U11"
      ]
    },
    {
      "text": "来访者在调班问题上存在难以开口、担心被看作‘事多’的困难；实际提出后晚班仍未调整，只补了半天调休。",
      "evidence_ids": [
        "P02-S01-U01",
        "P02-S02-U01"
      ]
    },
    {
      "text": "来访者面对应得之物（如调休）有‘配不配/欠’的自我怀疑，难以心安理得地使用，并提到这种模式‘从小就这样’。",
      "evidence_ids": [
        "P02-S02-U09",
        "P02-S02-U11"
      ]
    },
    {
      "text": "来访者对哥哥缺席陪伴母亲感到不指望/没意思，并倾向用‘没意思’带过去，较少直接表达失望或愤怒。",
      "evidence_ids": [
        "P02-S02-U03",
        "P02-S02-U05",
        "P02-S02-U15"
      ]
    },
    {
      "text": "来访者在值班室小床容易入睡，但在家夜间易醒，并警觉地关注母亲房间的动静。",
      "evidence_ids": [
        "P02-S03-U03",
        "P02-S03-U05",
        "P02-S03-U07",
        "P02-S03-U09"
      ]
    }
  ],
  "unresolved": [
    {
      "text": "调班需求未满足，晚班仍在；补的半天调休至今未使用，且伴随复杂情绪。",
      "evidence_ids": [
        "P02-S02-U01",
        "P02-S02-U11"
      ]
    },
    {
      "text": "来访者无法回应母亲‘都是拖累你’这类话语，话被堵住，形成额外情绪负担。",
      "evidence_ids": [
        "P02-S03-U03",
        "P02-S03-U04"
      ]
    },
    {
      "text": "夜间易醒并听母亲动静的警觉模式仍在持续，尚未找到缓解方式或安放母亲跌倒带来的惊吓/担忧。",
      "evidence_ids": [
        "P02-S03-U05",
        "P02-S03-U07",
        "P02-S03-U09"
      ]
    },
    {
      "text": "最新出现的午餐反胃身体反应尚未探索，与睡眠、情绪或照顾压力的关系不明。",
      "evidence_ids": [
        "P02-S03-U09"
      ]
    },
    {
      "text": "与哥哥的关系及对他缺席的失落尚未展开处理，来访者多次用‘没意思’/‘不指望’收住。",
      "evidence_ids": [
        "P02-S02-U03",
        "P02-S02-U05",
        "P02-S02-U15"
      ]
    },
    {
      "text": "‘欠/配不配’的感觉来源虽被提到‘从小就这样’，但尚未深入探讨其形成与影响。",
      "evidence_ids": [
        "P02-S02-U11"
      ]
    }
  ],
  "useful_exploration": [
    {
      "text": "探索‘松口气’与‘没良心’的拉扯，为来访者可能的个人喘息空间提供命名。",
      "evidence_ids": [
        "P02-S01-U03",
        "P02-S01-U04",
        "P02-S01-U06"
      ]
    },
    {
      "text": "探索候诊/家中‘站着不动’的折中状态，揭示其既无法真正陪伴母亲、也无法让自己休息的矛盾。",
      "evidence_ids": [
        "P02-S01-U07",
        "P02-S01-U08",
        "P02-S01-U09",
        "P02-S01-U10"
      ]
    },
    {
      "text": "探索调休单压在药盒下面的象征性安排，让来访者不必立刻决定它是休息还是欠账。",
      "evidence_ids": [
        "P02-S02-U13",
        "P02-S02-U14"
      ]
    },
    {
      "text": "探索‘没意思/不指望’之下可能是长期失望，虽然尚未被来访者完全承认，但打开了进一步讨论的空间。",
      "evidence_ids": [
        "P02-S02-U05",
        "P02-S02-U06"
      ]
    },
    {
      "text": "探索值班室小床与家中睡眠的对比，帮助区分身体疲劳与家庭场域中的情绪负担。",
      "evidence_ids": [
        "P02-S03-U03",
        "P02-S03-U04"
      ]
    },
    {
      "text": "探索两点多醒来听母亲房间动静的警觉状态，把‘怕再摔’的持续警觉摆到台面上。",
      "evidence_ids": [
        "P02-S03-U07",
        "P02-S03-U08"
      ]
    }
  ],
  "unsupported_assumptions": [
    {
      "text": "咨询师将‘没意思/不指望’解读为失望放久后结成的壳，但来访者明确说‘我也不是失望’，该解读未被确认。",
      "evidence_ids": [
        "P02-S02-U05",
        "P02-S02-U06"
      ]
    },
    {
      "text": "咨询师猜测‘也许真正让你不安的，是停下来什么都不做的那一刻’，来访者未确认，仅继续描述会去做事。",
      "evidence_ids": [
        "P02-S02-U07",
        "P02-S02-U08"
      ]
    },
    {
      "text": "咨询师把半夜醒来听动静解读为‘那阵惊吓还没找到机会真正落下来’，属于推测性情绪解释，来访者未直接确认。",
      "evidence_ids": [
        "P02-S03-U07",
        "P02-S03-U08"
      ]
    }
  ]
}
